// Normaliza e valida o CNPJ (numérico ou alfanumérico, vigente desde jul/2026)
const q = $input.first().json.query || {};
const bruto = String(q.cnpj || '').toUpperCase().replace(/[.\/\-\s]/g, '');

function dv(base) {
  let soma = 0, peso = 2;
  for (let i = base.length - 1; i >= 0; i--) {
    soma += (base.charCodeAt(i) - 48) * peso;
    peso = peso === 9 ? 2 : peso + 1;
  }
  const resto = soma % 11;
  return resto < 2 ? 0 : 11 - resto;
}

let motivo = null;
if (!bruto) motivo = 'Informe o parâmetro ?cnpj=';
else if (!/^[0-9A-Z]{12}[0-9]{2}$/.test(bruto)) motivo = 'CNPJ deve ter 14 caracteres: 12 letras/números + 2 dígitos verificadores';
else if (/^(.)\1{13}$/.test(bruto)) motivo = 'CNPJ com todos os caracteres iguais';
else {
  const d1 = dv(bruto.slice(0, 12));
  const d2 = dv(bruto.slice(0, 12) + d1);
  if (bruto.slice(12) !== `${d1}${d2}`) motivo = 'Dígitos verificadores não conferem';
}

const formatado = bruto.length === 14
  ? `${bruto.slice(0, 2)}.${bruto.slice(2, 5)}.${bruto.slice(5, 8)}/${bruto.slice(8, 12)}-${bruto.slice(12)}`
  : bruto;

return [{
  json: {
    cnpj: bruto,
    formato_valido: motivo === null,
    status: 400,
    body: {
      cnpj: formatado,
      formato_valido: false,
      registrado: false,
      valido: false,
      motivo,
    },
  },
}];

// Interpreta a resposta da BrasilAPI (dados públicos do CNPJ da Receita Federal)
const r = $input.first().json;
const cnpj = $('Validar CNPJ').first().json.cnpj;
const formatado = `${cnpj.slice(0, 2)}.${cnpj.slice(2, 5)}.${cnpj.slice(5, 8)}/${cnpj.slice(8, 12)}-${cnpj.slice(12)}`;
const status = r.statusCode;
const d = r.body || {};

if (status === 200) {
  const situacao = d.descricao_situacao_cadastral || null;
  return [{
    json: {
      status: 200,
      body: {
        cnpj: formatado,
        formato_valido: true,
        registrado: true,
        valido: situacao === 'ATIVA',
        situacao_cadastral: situacao,
        data_situacao_cadastral: d.data_situacao_cadastral || null,
        motivo_situacao_cadastral: d.descricao_motivo_situacao_cadastral || null,
        razao_social: d.razao_social || null,
        nome_fantasia: d.nome_fantasia || null,
        matriz_filial: d.descricao_identificador_matriz_filial || null,
        data_abertura: d.data_inicio_atividade || null,
        natureza_juridica: d.natureza_juridica || null,
        atividade_principal: d.cnae_fiscal_descricao || null,
        municipio: d.municipio || null,
        uf: d.uf || null,
        fonte: 'BrasilAPI (dados abertos da Receita Federal)',
        consultado_em: new Date().toISOString(),
      },
    },
  }];
}

if (status === 404) {
  return [{
    json: {
      status: 200,
      body: {
        cnpj: formatado,
        formato_valido: true,
        registrado: false,
        valido: false,
        motivo: 'CNPJ não encontrado na base da Receita Federal',
        consultado_em: new Date().toISOString(),
      },
    },
  }];
}

// 429, 5xx, timeout ou erro de rede: não dá para afirmar nada sobre o CNPJ
return [{
  json: {
    status: status === 429 ? 503 : 502,
    body: {
      cnpj: formatado,
      formato_valido: true,
      registrado: null,
      valido: null,
      motivo: status === 429
        ? 'Limite de consultas da fonte atingido, tente novamente em instantes'
        : `Falha ao consultar a fonte (${status || r.error?.message || r.error || 'erro de rede'})`,
    },
  },
}];
